name: Compliance Checks

on:
  push:
    branches: [main]
  pull_request:
    branches: [main]

jobs:
  check-compliance:
    runs-on: ubuntu-latest
    steps:
    - name: Set up repository
      uses: actions/checkout@v4

    - name: Validate Metadata Schema
      uses: ./.github/actions/metadata-validate
      env:
        ENFORCEMENT_TAGS: strategic_milestone,security_critical
      with:
        config-path: .github/metadata-schema.yaml

    - name: Audit Trail Verification
      uses: actions/github-script@v7
      with:
        script: |
          const { context } = require('@actions/github');
          const { ENFORCEMENT_TAGS } = process.env;
          const tags = ENFORCEMENT_TAGS.split(',');

          // Check if any enforcement-altering tags are present
          const hasEnforcementTag = tags.some(tag => 
            context.payload.head_commit.message.includes(tag)
          );

          if (hasEnforcementTag) {
            // Require explicit approval for enforcement-altering changes
            if (!process.env.AUTO_APPROVE) {
              core.setFailed('Enforcement-altering change detected. Requires explicit approval.');
            }
          }

    - name: Status Check
      uses: actions/status-check@v3
      with:
        required-statuses: compliance-check

